CREATE TABLE IF NOT EXISTS "users" (
	"user_id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"full_name" VARCHAR(255) NOT NULL,
	"email" VARCHAR(255) NOT NULL UNIQUE,
	"password" VARCHAR(255) NOT NULL,
	"join_date" TIMESTAMPTZ NOT NULL DEFAULT now(),
	"role" VARCHAR(50) NOT NULL DEFAULT 'USER' CHECK ("role" IN ('USER', 'ADMIN')),
	PRIMARY KEY("user_id")
);

CREATE TABLE IF NOT EXISTS "portfolio" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"user_id" INTEGER NOT NULL,
	"type" VARCHAR(255) NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "instrument" (
	"instrument_id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"symbol" VARCHAR(20) NOT NULL UNIQUE,
	"full_name" VARCHAR(255) NOT NULL,
	PRIMARY KEY("instrument_id")
);

CREATE TABLE IF NOT EXISTS "holding" (
	"holding_id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"order_date" TIMESTAMPTZ NOT NULL DEFAULT now(),
	"portfolio_id" INTEGER NOT NULL,
	"quote" DECIMAL(19, 6) NOT NULL,
	"quantity" DECIMAL(19, 6) NOT NULL,
	PRIMARY KEY("holding_id")
);

CREATE TABLE IF NOT EXISTS "orders" (
	"order_id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"instr_id" INTEGER NOT NULL,
	"place_date" TIMESTAMPTZ NOT NULL DEFAULT now(),
	"type" VARCHAR(255) NOT NULL,
	"status" VARCHAR(255) NOT NULL DEFAULT 'PENDING',
	"user_id" INTEGER NOT NULL,
	"holding_id" INTEGER,
	"quote" DECIMAL(19, 6) NOT NULL,
	"actual_price" DECIMAL(19, 6),
	"quantity" DECIMAL(19, 6) NOT NULL,
	PRIMARY KEY("order_id")
);

ALTER TABLE "portfolio"
	ADD FOREIGN KEY("user_id") REFERENCES "users"("user_id")
	ON UPDATE NO ACTION ON DELETE NO ACTION;

ALTER TABLE "holding"
	ADD FOREIGN KEY("portfolio_id") REFERENCES "portfolio"("id")
	ON UPDATE NO ACTION ON DELETE NO ACTION;

ALTER TABLE "orders"
	ADD FOREIGN KEY("holding_id") REFERENCES "holding"("holding_id")
	ON UPDATE NO ACTION ON DELETE NO ACTION;

ALTER TABLE "orders"
	ADD FOREIGN KEY("user_id") REFERENCES "users"("user_id")
	ON UPDATE NO ACTION ON DELETE NO ACTION;

ALTER TABLE "orders"
	ADD FOREIGN KEY("instr_id") REFERENCES "instrument"("instrument_id")
	ON UPDATE NO ACTION ON DELETE NO ACTION;

CREATE INDEX ON "portfolio" ("user_id");
CREATE INDEX ON "holding" ("portfolio_id");
CREATE INDEX ON "orders" ("user_id");
CREATE INDEX ON "orders" ("instr_id");
CREATE INDEX ON "orders" ("holding_id");
